import CoverPicker from "./CoverPicker.svelte";

describe("cover upload feedback", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    vi.stubGlobal("matchMedia", () => ({ matches: false }));
  });
  afterEach(() => vi.unstubAllGlobals());

  it.each(["photo.jpeg", "photo.heic"])("accepts %s", async (name) => {
    mocks.upload.mockResolvedValue([{ id: "file:cover" }]);
    const onSelect = vi.fn();
    const { container, getByText } = render(CoverPicker, { onSelect });
    const file = new File(["image"], name, { type: "image/jpeg" });
    await fireEvent.change(container.querySelector('input[type="file"]')!, {
      target: { files: [file] }
    });
    await waitFor(() => expect(mocks.upload).toHaveBeenCalled());
    expect(mocks.upload.mock.calls[0][1]).toBe(name);
    await waitFor(() => expect(getByText("Click to replace")).toBeVisible());
    expect(onSelect).toHaveBeenCalledOnce();
    expect(onSelect.mock.calls[0][0].detail).toBe("file:cover");
    expect(mocks.error).not.toHaveBeenCalled();
  });

  it("reports rejected formats without uploading", async () => {
    const { container } = render(CoverPicker);
    await fireEvent.change(container.querySelector('input[type="file"]')!, {
      target: { files: [new File(["text"], "cover.txt")] }
    });
    expect(mocks.upload).not.toHaveBeenCalled();
    expect(mocks.error).toHaveBeenCalledWith(
      "Please select a JPG, JPEG, PNG, HEIC, or PDF file."
    );
  });

  it("reports upload rejection and clears the progress indicator", async () => {
    mocks.upload.mockRejectedValue(new Error("transport failed"));
    const { container, queryByText } = render(CoverPicker);
    await fireEvent.change(container.querySelector('input[type="file"]')!, {
      target: { files: [new File(["image"], "cover.png")] }
    });
    await waitFor(() =>
      expect(mocks.error).toHaveBeenCalledWith(
        "Failed to upload cover. Please try again."
      )
    );
    expect(queryByText("Uploading...")).toBeNull();
  });

  it("reports oversized files without uploading", async () => {
    const { container } = render(CoverPicker);
    const file = new File(["image"], "cover.png");
    Object.defineProperty(file, "size", { value: 16 * 1024 * 1024 });
    await fireEvent.change(container.querySelector('input[type="file"]')!, {
      target: { files: [file] }
    });
    expect(mocks.upload).not.toHaveBeenCalled();
    expect(mocks.error).toHaveBeenCalledWith(
      "Please select a file smaller than 15 MB."
    );
  });
});

import { writable } from "svelte/store";
import { Display } from "@21n/elements/display.enum";
import { type IViewStore } from "@21n/elements/environment/view.type";
import { ObservableStore } from "@nucleum/stores/client.store";

/**
 * Programmatically set the screen size - Refer tidigit.tailwind.cjs for more details
 * @param width
 * @param height
 * @returns
 */
function calculateScreen(width: number, height: number): Display {
  let display: Display = Display.DP;
  if (width <= 600 && height <= 1000) {
    display = Display.MO;
  }
  if (width >= 600 && height >= 500) {
    display = Display.TP;
  }
  if (width >= 1024 && height >= 700) {
    display = Display.LP;
  }
  if (width >= 1500 && height >= 700) {
    display = Display.DP;
  }
  if (width >= 2000 && height >= 1000) {
    display = Display.TK;
  }
  if (width <= 600) {
    display = Display.CW;
  }
  if (width >= 4000) {
    display = Display.UW;
  }
  if (height <= 600) {
    display = Display.CH;
  }
  if (height >= 1500) {
    display = Display.VM;
  }
  return display;
}

/**
 * @deprecated - use ViewStore instead
 */
const viewV1 = initViewStore({
  height: 0,
  width: 0,
  landscapiness: 0,
  scale: 1,
  isPortrait: false,
  firstLoad: new Date().getTime(),
  currentPath: "",
  isMenuHidden: false,
  display: Display.DP,
  isConstrainedWidth: false
});

/**
 * @deprecated - use ViewStore instead
 */
function initViewStore(settings: IViewStore) {
  const { subscribe, set, update } = writable<IViewStore>(settings);
  return {
    subscribe,
    set,
    reset: (view: IViewStore) => {
      set(view);
    },
    update: (width: number, height: number) => {
      update((n: IViewStore) => {
        n = {
          ...n,
          height: height,
          width: width,
          landscapiness: width / height,
          scale: (width / 1000 + height / 1000) / 2,
          isPortrait: false,
          isConstrainedWidth: width <= 800
        };
        n.display = calculateScreen(width, height);
        n.isPortrait = n.landscapiness < 1;
        return n;
      });
    }
  };
}

class ViewStore extends ObservableStore<IViewStore> {
  constructor() {
    super("view");
    if (typeof window !== "undefined")
      this.refresh(window.innerWidth, window.innerHeight);
    else this.refresh(1080, 900);
  }

  reset(view: IViewStore) {
    this.set(view);
  }

  refresh(width: number, height: number) {
    this.update((n: IViewStore) => {
      n = {
        ...n,
        height: height,
        width: width,
        landscapiness: width / height,
        scale: (width / 1000 + height / 1000) / 2,
        isPortrait: false,
        isConstrainedWidth: width <= 800
      };
      n.display = calculateScreen(width, height);
      n.isPortrait = n.landscapiness < 1;
      return n;
    });
  }
}

const view = new ViewStore();
export default view;
import type { Display } from "@21n/elements/display.enum";
import type { IContainer } from "@21n/layout/layout.type";
import type { IAction } from "@nucleum/client/config/action.type";

export type IViewStore = IContainer & {
  scale: number;
  display: Display;
  isMinimalTopBar?: boolean;
  firstLoad: number;
  /**
   * Used in cases like not rendering resources with cantilever buttons on small screens and other places throughout the app to check if the screen width is constrained. This is a proxy for Display.CW or Display.MO
   */
  isConstrainedWidth: boolean;
  /**
   * @deprecated - use appStore.currentPath
   */
  currentPath: string;
  /**
   * @deprecated - use appStore.isMenuHidden
   */
  isMenuHidden: boolean;
  /**
   * @deprecated - use appStore.currentComponent
   */
  currentComponent?: IAction;
  /**
   * @deprecated - use appStore.sheetPath
   */
  sheetPath?: string;
};

