import { navigation } from "@21n/layout/navigation/navigation";
import { requireCommandHost } from "@nucleum/stores/commands/command-host";
import { actionRunner } from "../commands/action-runner";
import { configureCommandHost } from "@nucleum/stores/commands/command-host";
import { configureProductResourceTables } from "@nucleum/client/config/product-resources";
import { configureActionRenderer } from "@nucleum/stores/resources/action-renderer";
import ComponentResolver from "@21n/layout/paint/ComponentResolver.svelte";
import { get } from "svelte/store";
import { appStore } from "@nucleum/stores/app.store";
import { AppSearchParam } from "@nucleum/stores/appStore.type";
import { appEvents } from "@nucleum/stores/events/app-events.store";
import { tabs } from "@21n/layout/topNav/tabs/tabs.store";
import { AccessMode } from "@nucleum/datafn/resource.type";
import { resolveProductResources } from "@nucleum/datafn/resource.utils";
import { Action } from "@nucleum/client/config/action.enum";
import { configureOverlayHost } from "@nucleum/stores/overlays/modal.store";
import { configureRecordRenderer } from "@nucleum/stores/resources/record-renderer";
import { configureShortcutHost } from "@nucleum/stores/keyboard/shortcut-host";
import { configureRecentsHost } from "@nucleum/stores/resources/recent-host";
import { configureResourcePanelHost } from "@nucleum/stores/resources/resource-panel-host";
import { configureResourceActionHost } from "@nucleum/stores/resources/resource-action-host";
import { resolveProductConfig } from "@nucleum/products/product.config";
import { shortcutsConfig } from "../shortcuts/shortcuts.config";
import { copyResourceLinkToClipboard } from "../record/resource-link.utils";
import Records from "../record/Records.svelte";

configureOverlayHost({
  onDismiss: (action) => appEvents.nav(action),
  openFullscreen: (path) =>
    navigation.toggleSearchParam({
      [AccessMode.FULL]: path,
      [AccessMode.POP]: null
    }),
  closeFullscreen: () => navigation.toggleSearchParam([AccessMode.FULL]),
  resolvePlayer: (path) =>
    appStore.resolveComponentFromPath(path)?.associatedPlayer
});

configureShortcutHost({
  defaults: shortcutsConfig,
  configurableActions: () => resolveProductConfig().configurableShortcuts
});

configureRecordRenderer(Records);

configureRecentsHost({
  resources: () => resolveProductResources(get(appStore).product)
});

configureResourcePanelHost({
  readPanel: (id, url) => {
    return url.searchParams.get(
      navigation.resolveRecordSpecificSearchParam(id, AppSearchParam.PANEL)
    );
  },
  writePanel: (id, panel) =>
    navigation.toggleSearchParamRecordSpecific(id, {
      [AppSearchParam.PANEL]: panel
    }),
  close: (id) => navigation.closeResource({ id }),
  goBack: () => navigation.goBack(),
  maximize: (mode, id) => navigation.toggleFullScreen(mode, id)
});

configureResourceActionHost({
  copyLink: copyResourceLinkToClipboard,
  open: (id, mode, options) => navigation.openResource(id, mode, options),
  close: (options) => navigation.closeResource(options),
  maximize: (mode, id) => navigation.toggleFullScreen(mode, id),
  openTab: (id) => tabs.open(id),
  removeTab: (id) => tabs.remove(id),
  requestLink: (options) =>
    requireCommandHost().runAction(Action.BULK_LINK, {
      componentParams: options
    }),
  afterNodeMutation: async (action, ids) => {
    const lifecycle = await import("@nucleum/features/memory/node/node.store");
    if (action === "archive") return lifecycle.onNodeArchive(ids);
    if (action === "unarchive") return lifecycle.onNodeUnarchive(ids);
    return lifecycle.onNodeTrash(ids);
  }
});

configureActionRenderer(ComponentResolver);
configureProductResourceTables(
  (product) => resolveProductConfig(product).resources.table
);

configureCommandHost(actionRunner);
import type { Component } from "svelte";

/** Application action presentation used by shared controls with named custom cells. */
export type ActionRenderer = Component<{ path?: string; params?: any }>;

let renderer: ActionRenderer | undefined;

/** Installs named-action rendering from the application shell. */
export function configureActionRenderer(value: ActionRenderer) {
  renderer = value;
}

/** Requires application composition only when rendering a named action. */
export function requireActionRenderer(): ActionRenderer {
  if (!renderer) throw new Error("Action renderer has not been configured");
  return renderer;
}
import type { IAction } from "@nucleum/client/config/action.type";
import type { Resource } from "@nucleum/datafn/resource.enum";
import type { ResourceActionType } from "@nucleum/schema/legacy/resource-action.enum";

/** Application command execution supplied by the composing shell. */
export interface CommandHost {
  resolveAction(slug: string): IAction | null;
  runAction(
    slug: string,
    params?: {
      componentParams?: any;
      isReturnIfComponent?: boolean;
      searchParams?: Record<string, string | boolean | number>;
    }
  ): any;
  runResourceAction(
    resource: Resource,
    action: ResourceActionType,
    params?: any
  ): any;
}
let commandHost: CommandHost | undefined;
/** Installs the product command executor before mounting application surfaces. */
export function configureCommandHost(host: CommandHost) {
  commandHost = host;
}
/** Requires the composing shell to supply command behavior. */
export function requireCommandHost(): CommandHost {
  if (!commandHost) throw new Error("Command host has not been configured");
  return commandHost;
}
<script lang="ts">
  import { resolveShortcutText } from "@21n/elements/keyboard/shortcut.utils";
  import { keyboardShortcuts } from "@nucleum/stores/keyboard/shortcuts.store";
  import { elementPlatform as context } from "@21n/elements/environment/element-environment.store";
  import { GlobalEvent } from "@nucleum/stores/notifications/event.enum";
  import { Size } from "@21n/elements/size.enum";
  import { bg, cn } from "@21n/utils/ui.utils";
  import Icon from "@21n/elements/Icon.svelte";
  import type { IKeyboardShortcut } from "@21n/elements/keyboard/shortcut.type";
  import { KeyboardKey } from "@21n/elements/keyboard/keyboard.type";
  import { shortcutHints } from "@nucleum/stores/keyboard/shortcut-hints.store";

  let {
    shortcut,
    parentBgIndex = undefined,
    isPlainText = false,
    isAccentOutlined = false,
    size = Size.md,
    isAlwaysShown = false
  }: {
    shortcut: string | IKeyboardShortcut | undefined;
    parentBgIndex?: number | undefined;
    isPlainText?: boolean;
    isAccentOutlined?: boolean;
    size?: Size.sm | Size.md;
    isAlwaysShown?: boolean;
  } = $props();

  const iconKeys = new Map<KeyboardKey, string>([
    // [KeyboardKey.ENTER, "arrow-turn-down-left"],
    // [KeyboardKey.ARROW_LEFT, "arrow-left"],
    // [KeyboardKey.ARROW_RIGHT, "proceed"],
    // [KeyboardKey.ARROW_UP, "arrow-up"],
    // [KeyboardKey.ARROW_DOWN, "arrow-down"]
  ]);
  const textReplacements = [
    { key: KeyboardKey.ESCAPE, text: "Esc" },
    { key: KeyboardKey.ENTER, text: "Enter" },
    { key: KeyboardKey.ARROW_RIGHT, text: "→" },
    { key: KeyboardKey.ARROW_LEFT, text: "←" },
    { key: KeyboardKey.ARROW_UP, text: "↑" },
    { key: KeyboardKey.ARROW_DOWN, text: "↓" }
  ];

  const detail = $derived.by((): IKeyboardShortcut | undefined => {
    $keyboardShortcuts;
    if (!shortcut) {
      return;
    }
    if (typeof shortcut !== "string") {
      return shortcut;
    }
    if (shortcut === GlobalEvent.ESCAPE) {
      return;
    }
    return keyboardShortcuts.resolveShortcutForAction(shortcut);
  });
  const text = $derived.by(() => {
    if (!shortcut) return;
    if (typeof shortcut === "string" && shortcut === GlobalEvent.ESCAPE) {
      return "Esc";
    }
    if (!detail) return;
    return resolveShortcutText({
      key: detail.key,
      modifiers: detail.modifiers,
      os: $context.os
    });
  });
  const trimmedText = $derived(text?.trim());
  const shortcutKey = $derived(detail?.key as KeyboardKey | undefined);
  const isSingleLetterShortcut = $derived(
    !!trimmedText &&
      Array.from(trimmedText).length === 1 &&
      (!detail?.modifiers || detail?.modifiers.length === 0)
  );
</script>

{#if ($shortcutHints?.isShowHotKeyHints || isAlwaysShown) && shortcut && $context.embed !== "HANDSET" && $context.embed !== "TABLET"}
  <span
    class={cn(
      "flex justify-center items-center whitespace-nowrap font--mono rounded-md",
      {
        "text-b4  min-h-[1.125rem] h-[1.125rem]": size === Size.md,
        "text-b5": size === Size.sm,
        "border-ccs2": isAccentOutlined
      },
      isSingleLetterShortcut && {
        "px-0 py-0": true,
        "min-w-[1.125rem] w-[1.125rem] ": size === Size.md,
        "min-w-3.5 w-3.5 min-h-3.5 h-3.5": size === Size.sm
      },
      !isSingleLetterShortcut && {
        "px-1 min-h-4 h-4": size === Size.sm,
        "px-1.5": size === Size.md
      },
      !isPlainText && {
        "border-[0.5px]":
          (isSingleLetterShortcut && size === Size.sm && !isAccentOutlined) ||
          !isSingleLetterShortcut,
        border: (size !== Size.sm || isAccentOutlined) && isSingleLetterShortcut
      },
      !isPlainText &&
        !isAccentOutlined && {
          [bg(parentBgIndex)]: parentBgIndex !== undefined,
          "text-fgs3 border-brs3": parentBgIndex !== undefined,
          "border-abg opacity-80": parentBgIndex === undefined
        }
    )}
  >
    {#if shortcutKey && iconKeys.has(shortcutKey)}
      {text?.replace(shortcutKey.toUpperCase(), "") ?? ""}
      <Icon
        icon={iconKeys.get(shortcutKey)}
        size={Size.xs}
        class={cn({
          "text-fgs3": parentBgIndex !== undefined,
          "text-abg": parentBgIndex === undefined && !isAccentOutlined,
          "text-aps1": parentBgIndex === undefined && isAccentOutlined
        })}
      />
    {:else if text && textReplacements.some( (x) => text?.includes(x.key.toUpperCase()) )}
      {@const replacement = textReplacements.find((x) =>
        text?.includes(x.key.toUpperCase())
      )}
      {text.replace(
        replacement?.key?.toUpperCase() ?? "",
        replacement?.text ?? ""
      ) ?? ""}
    {:else}
      {text ?? ""}
    {/if}
  </span>
{/if}
import { ModifierKey } from "@21n/elements/keyboard/keyboard.type";
import { elementLogger as logger } from "@21n/elements/environment/element-environment.store";

export function resolveShortcutText(params: {
  key: string;
  os: string;
  modifiers?: ModifierKey[];
}) {
  const { key, modifiers, os } = params;
  let modifierLabels: string[] = [];
  logger.log({ key, modifiers, os });
  if (modifiers && modifiers.length > 0) {
    modifierLabels = modifiers.map((x) => {
      if (x === ModifierKey.META) {
        if (os === "MACOS" || os === "IOS") {
          return "⌘";
        } else {
          return "Win";
        }
      } else if (x === ModifierKey.CTRL) {
        return "Ctrl";
      } else return x;
    });
  }
  if (modifierLabels.length === 0) return key.toUpperCase();
  return modifierLabels.join(" + ") + (key ? " + " + key.toUpperCase() : "");
}

export function resolveModifiers(event: KeyboardEvent) {
  let modifiers: ModifierKey[] = [];
  if (event.metaKey) {
    modifiers.push(ModifierKey.META);
  }
  if (event.ctrlKey) {
    modifiers.push(ModifierKey.CTRL);
  }
  if (event.altKey) {
    modifiers.push(ModifierKey.ALT);
  }
  if (event.shiftKey) {
    modifiers.push(ModifierKey.SHIFT);
  }
  return modifiers;
}

