  if (!data) {
    const token = shouldUseAuthFnBearerSession()
      ? await clientStorage.get(ClientStorageKey.AUTHFN_TOKEN)
      : undefined;
    const userInfo = parse(
      (await clientStorage.get(ClientStorageKey.USER_INFO)) ?? ""
    );
    data = { token, userInfo };
  }
