    searchStoreId = undefined,
    searchResultComponent = undefined,
    searchResultComponentProps = {},
    shortcutTrigger = undefined,
    shortcutTriggers = [],
    emptyStateLabel = "No results found",
    isPreventDefaultResults = false,
    isInlineContext = false,
