    bottomMessage?: string | undefined;
    onSelect?: Function | undefined;
    onReset?: Function | undefined;
    onHide?: ((event: CustomEvent<void>) => void) | undefined;
    onShow?: ((event: CustomEvent<void>) => void) | undefined;
