function initContextStore(val: IAppContext) {
  const { subscribe, set, update } = writable<IAppContext>(val);
  return {
    subscribe,
    set,
    update,
    toggleOfflineMode: async (value: boolean) => {
      try {
        await clientStorage.set(ClientStorageKey.OFFLINE_MODE, value);
