const r = await tools.exec_command({
  cmd: "for d in appearance files notifications preferences resources shortcuts; do echo \"[$d]\"; find \"client/$d\" -maxdepth 2 -type f | sort; rg -n '^\\s*(import|export).*from\\s+[\"'\"']|^\\s*import\\([\"'\"']' \"client/$d\" --glob '!**/*.test.ts' --glob '!**/*.spec.ts' || true; done\nprintf '\\n[ui environment/hosts imports]\\n'\nrg -n '^\\s*(import|export).*from\\s+[\"'\"']' client/ui/elements/environment client/ui/elements/hosts || true\nprintf '\\n[workspace refs]\\n'\nrg -n 'client/(appearance|files|notifications|preferences|resources|shortcuts)|@nucleum/client/(appearance|files|notifications|preferences|resources|shortcuts)|@21n/ui/elements/(environment|hosts)' package.json package-lock.json tsconfig.json client/tsconfig.json tools/alias-map.json client/**/package.json apps/**/package.json extensions/**/package.json --glob '!**/node_modules/**'",
  workdir: "/Users/serro/Documents/dev/n/nucleus",
  yield_time_ms: 10000,
  max_output_tokens: 30000
});
text(r.output);

