      dapId: "fixture",
      env: `test-${crypto.randomUUID()}`
    };
    await initializeNucleumDatafn(boot);
    account.set({ ...initialAccount, dataMode: UserDataMode.LOCAL });
    const signedUrl = vi.spyOn(persistenceInstance, "getSignedUrl");
