  // import spritePhLight from "data-text:/assets/icons/sprite-ph-light.svg";
  import { resolveIconSvgSheetText } from "@nucleum/extensions/iconSvgSheetTextResolver";
  import { appStore } from "@nucleum/client/state/app.store";
  import {
    isRecordId,
