import { FluxMethod, IFluxMethod } from "$lib/client/components/flux/flux.type";
import { Agent } from "$lib/server/common/account/account.type";

import { ValidationError } from "../errors";
import { SyncProviderFactory } from "../sync/providers";

export function relay(body: IFluxMethod, agent: Agent) {
  const provider = SyncProviderFactory.getProvider();
  switch (body.method) {
    case FluxMethod.SELECT_MANY:
      const { resource, params } = body.args;
      if (!resource) {
        throw new ValidationError("resource is required");
      }
      return provider.selectMany(agent, resource, params);
    case FluxMethod.SELECT:
      const { resourceId, properties } = body.args;
      if (!resourceId) {
        throw new ValidationError("resourceId is required");
      }
      return provider.select(agent, resourceId, properties);
    default:
      return {
        statusCode: 400,
        body: "Method not found"
      };
  }
}
import { describe, it, expect } from "vitest";
import { Resource } from "$lib/client/components/flux/resourceStores/resource.enum";
import { relay } from ".";
import { FluxMethod } from "$lib/client/components/flux/flux.type";

/**
 * Integration test for DynamoDB provider selectMany method with mutation resource.
 * This test uses the actual DynamoDB implementation without mocking.
 */
describe("DynamoDB Provider - Relay Resource", () => {
  const resourceId = "goal:lpez0ylr97p5c";

  it("should query mutation resource using GSI1 index pattern", async () => {
    const result = await relay(
      {
        method: FluxMethod.SELECT_MANY,
        args: {
          resource: Resource.mutation,
          params: { filters: { resourceId: resourceId } }
        }
      },
      global.testEnv.agent
    );
    console.log({ result });
    expect(result).toBeDefined();
    expect(Array.isArray(result)).toBe(true);
  });

  it("should query accessLog resource", async () => {
    const result = await relay(
      {
        method: FluxMethod.SELECT_MANY,
        args: {
          resource: Resource.accessLog,
          params: { filters: { resourceId: resourceId } }
        }
      },
      global.testEnv.agent
    );
    console.log({ result });
    expect(result).toBeDefined();
    expect(Array.isArray(result)).toBe(true);
  });

  it.only("should query mutation resource with filters", async () => {
    const result = await relay(
      {
        method: FluxMethod.SELECT_MANY,
        args: {
          resource: Resource.mutation,
          params: {
            filters: {
              action: ["create", "delete"],
              resource: ["node", "collection", "tz"],
              timestamp: {
                greaterThanOrEqual: 1750703400000,
                lessThanOrEqual: 1750789800000
              }
            }
          }
        }
      },
      global.testEnv.agent
    );
    console.log({ result });
    expect(result).toBeDefined();
    expect(Array.isArray(result)).toBe(true);
  });
});
