  page: Page,
  composition: SessionCompositionInput
) {
  await page.evaluate(
    async ({ modulePaths, composition }) => {
      const sessionMod = await import(modulePaths.sessionStorePath);
      const draftMod = await import(
        modulePaths.advancedCompositionDraftStorePath
