import type { Resource } from "@nucleum/schema/resource.enum";
import type {
  IRecordId,
  IResourceSelectParams,
  IResourceSelectProperties
} from "@nucleum/schema/legacy/data.type";

/** Operations still accepted by the legacy relay endpoint. */
export enum FluxMethod {
  SELECT_MANY = "selectMany",
  SELECT = "select"
}

/** Request payload accepted by the legacy relay endpoint. */
export type IFluxMethod =
  | {
      method: FluxMethod.SELECT_MANY;
      args: {
        resource: Resource;
        params?: IResourceSelectParams;
      };
    }
  | {
      method: FluxMethod.SELECT;
      args: {
        resourceId: IRecordId;
        properties?: IResourceSelectProperties;
      };
    };
import { FluxMethod, type IFluxMethod } from "./relay.type";
import { Agent } from "$lib/server/common/account/account.type";

import { ValidationError } from "../errors";
import { SyncProviderFactory } from "../sync/providers";

export function relay(body: IFluxMethod, agent: Agent) {
  const provider = SyncProviderFactory.getProvider();
  switch (body.method) {
    case FluxMethod.SELECT_MANY:
      const { resource, params } = body.args;
      if (!resource) {
        throw new ValidationError("resource is required");
      }
      return provider.selectMany(agent, resource, params);
    case FluxMethod.SELECT:
      const { resourceId, properties } = body.args;
      if (!resourceId) {
        throw new ValidationError("resourceId is required");
      }
      return provider.select(agent, resourceId, properties);
    default:
      return {
        statusCode: 400,
        body: "Method not found"
      };
  }
}

