}

/** Installs optional host interaction feedback. */
export function configureElementHaptic(value: () => void) {
  haptic = value;
}

/** Installs portable asset URL resolution supplied by the host application. */
export function configureElementAssetPath(
  value: (path: string) => string
) {
  assetPathResolver = value;
}

/** Resolves an application-hosted asset without coupling UI to product storage. */
export function resolveElementAssetPath(path: string) {
  return assetPathResolver(path);
}

/** Requests interaction feedback when the host supports it. */
export function elementHaptic() {
  haptic();
}
import { navigation } from "@nucleum/application/shell/navigation/navigation";
import { requireCommandHost } from "@nucleum/client/commands/command-host";
import { actionRunner } from "../commands/action-runner";
import { configureCommandHost } from "@nucleum/client/commands/command-host";
import { configureProductResourceTables } from "@nucleum/client/config/product-resources";
import { configureActionRenderer } from "@nucleum/capabilities/resources/action-renderer";
import ComponentResolver from "@nucleum/application/shell/paint/ComponentResolver.svelte";
import { get } from "svelte/store";
import { appStore } from "@nucleum/capabilities/app-context/app.store";
import { AppSearchParam } from "@nucleum/capabilities/app-context/app-store.type";
import { appEvents } from "@nucleum/client/events/app-events.store";
import { tabs } from "@nucleum/application/shell/topNav/tabs/tabs.store";
import { AccessMode } from "@nucleum/datafn/resource.type";
import {
  determineResourceType,
  resolveProductResources
} from "@nucleum/datafn/resource.utils";
import { Action } from "@nucleum/client/config/action.enum";
import { configureOverlayHost } from "@nucleum/application/shell/overlays/modal.store";
import { configureRecordRenderer } from "@nucleum/capabilities/resources/record-renderer";
import { configureShortcutHost } from "@nucleum/capabilities/shortcuts/shortcut-host";
import { configureRecentsHost } from "@nucleum/capabilities/resources/recent-host";
import { configureResourcePanelHost } from "@nucleum/capabilities/resources/resource-panel-host";
import { configureResourceActionHost } from "@nucleum/capabilities/resources/resource-action-host";
import { resolveProductConfig } from "@nucleum/products/product.config";
import { shortcutsConfig } from "../shortcuts/shortcuts.config";
import { copyResourceLinkToClipboard } from "../record/resource-link.utils";
import Records from "../record/Records.svelte";
import { configureElementActionHost } from "@21n/ui/hosts/action-host";
import { configureElementShortcutHost } from "@21n/ui/hosts/shortcut-host";
import { keyboardShortcuts } from "@nucleum/capabilities/shortcuts/shortcuts.store";
import FileView from "@21n/ui/compositions/files/FileView.svelte";
import { configureElementFileHost } from "@21n/ui/hosts/file-host";
import { configureElementSearchHost } from "@21n/ui/hosts/search-host";
import { fileStore } from "@nucleum/capabilities/files/file.store";
import {
  configureElementAssetPath,
  configureElementHaptic,
  configureElementLogger,
  syncElementPlatform
} from "@21n/ui/environment/element-environment.store";
import { logger } from "@nucleum/client/runtime/logging/logger";
import { haptic } from "@nucleum/client/runtime/embed/embed.utils";
import { assetPath } from "@nucleum/static";
import context from "@nucleum/client/runtime/context.store";

configureOverlayHost({
  onDismiss: (action) => appEvents.nav(action),
  openFullscreen: (path) =>
    navigation.toggleSearchParam({
      [AccessMode.FULL]: path,
      [AccessMode.POP]: null
    }),
  closeFullscreen: () => navigation.toggleSearchParam([AccessMode.FULL]),
  resolvePlayer: (path) =>
    appStore.resolveComponentFromPath(path)?.associatedPlayer
});

configureShortcutHost({
  defaults: shortcutsConfig,
  configurableActions: () => resolveProductConfig().configurableShortcuts
});

configureRecordRenderer(Records);

configureRecentsHost({
  resources: () => resolveProductResources(get(appStore).product)
});

configureResourcePanelHost({
  readPanel: (id, url) => {
    return url.searchParams.get(
      navigation.resolveRecordSpecificSearchParam(id, AppSearchParam.PANEL)
    );
  },
  writePanel: (id, panel) =>
    navigation.toggleSearchParamRecordSpecific(id, {
      [AppSearchParam.PANEL]: panel
    }),
  close: (id) => navigation.closeResource({ id }),
  goBack: () => navigation.goBack(),
  maximize: (mode, id) => navigation.toggleFullScreen(mode, id)
});

configureResourceActionHost({
  copyLink: copyResourceLinkToClipboard,
  open: (id, mode, options) => navigation.openResource(id, mode, options),
  close: (options) => navigation.closeResource(options),
  maximize: (mode, id) => navigation.toggleFullScreen(mode, id),
  openTab: (id) => tabs.open(id),
  removeTab: (id) => tabs.remove(id),
  requestLink: (options) =>
    requireCommandHost().runAction(Action.BULK_LINK, {
      componentParams: options
    }),
  afterNodeMutation: async (action, ids) => {
    const lifecycle = await import("@nucleum/features/memory/node/node.store");
    if (action === "archive") return lifecycle.onNodeArchive(ids);
    if (action === "unarchive") return lifecycle.onNodeUnarchive(ids);
    return lifecycle.onNodeTrash(ids);
  }
});

configureActionRenderer(ComponentResolver);
configureElementActionHost({
  openLink: (href) => navigation.openLink(href),
  renderer: ComponentResolver,
  runAction: (action, params) => requireCommandHost().runAction(action, params)
});
configureElementSearchHost({
  onSelected: (item) => {
    if (typeof item.id !== "string") return;
    appStore.addToRecents({
      record: {
        ...item,
        bodySearch: undefined,
        labelSearch: undefined
      },
      type: determineResourceType(item.id),
      timestamp: new Date()
    });
  }
});
configureElementShortcutHost({
  resolve: (action) => keyboardShortcuts.resolveShortcutForAction(action)
});
configureElementFileHost({
  renderer: FileView,
  resolve: (file, options) => fileStore.refresh(file as any, options)
});
configureElementLogger(logger);
configureElementHaptic(haptic);
configureElementAssetPath(assetPath);
context.subscribe(syncElementPlatform);
configureProductResourceTables(
  (product) => resolveProductConfig(product).resources.table
);

configureCommandHost(actionRunner);
