          ? process.env?.PLASMO_PUBLIC_API_AS_URL
          : undefined)
      );
    }
  } catch (e) {
    console.warn("Error in resolveRegionalApiUrl", e);
  }
}

export function resolveRegionalApiUrlStrategy(): string {
